/**
 * block_enhancedcourseoverview/filter
 *
 * Hand-built AMD equivalent of amd/src/filter.js.
 *
 * This repository does not include Moodle's own build tooling (Grunt +
 * the moodle-local babel/rollup config live in Moodle core), so this file
 * cannot be generated with `grunt amd` here. It is a faithful, manually
 * written AMD translation of the ES module in amd/src/filter.js, kept in
 * sync by hand. Once this plugin is dropped into a full Moodle checkout,
 * regenerate the canonical minified/versioned build with:
 *
 *   grunt amd --root=blocks/enhancedcourseoverview
 *
 * and commit the result over this file.
 */
define(['core/str', 'core/ajax'], function (Str, Ajax) {
    'use strict';

    var SELECTORS = {
        FILTER_BUTTON: '.filter-term-btn',
        GROUP_TOGGLE: '.filter-group-toggle',
        GROUP: '.btn-group',
        COURSES_VIEW: '[data-region="courses-view"]',
        PAGING_BAR: '[data-region="paging-bar"]',
        PAGING_CONTROLS: '[data-region="paging-control-container"]',
        NEXT_CONTROL: '[data-control="next"]',
        PAGE_LINK: '[data-region="page-link"]',
        LIMIT_ALL_OPTION: '[data-limit="0"]',
        PAGE: '[data-region="paged-content-page"]',
        COURSE_ITEM: '[data-region="course-content"]',
        COURSE_NAME: '.coursename',
        COLUMN: '.col.d-flex, .col'
    };

    var AJAX_SETTLE_TIMEOUT_MS = 8000;
    var INITIAL_RENDER_TIMEOUT_MS = 15000;
    var INITIAL_RENDER_POLL_MS = 150;
    var MAX_NEXT_CLICKS = 500;
    var VIEW_CHANGE_DEBOUNCE_MS = 300;
    var ROLE_CATEGORY = 'role';
    var DEFAULT_CATEGORY = 'term';

    // Cache of pattern string -> compiled RegExp (or null for a plain
    // substring pattern), shared across every filter instance on the page.
    var patternCache = new Map();

    var escapeRegExp = function (text) {
        return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    };

    // Compile a pattern into a RegExp if it uses either opt-in syntax below,
    // or return null to mean "match as a plain substring" (unchanged,
    // original behaviour). Every existing plain-text pattern (e.g.
    // "_A_2_202425") uses neither syntax, so it keeps matching exactly as
    // before.
    //
    // 1. Digit wildcard: a "*" matches a run of zero or more digits (not
    //    arbitrary text). Handles course codes that combine multiple terms
    //    into one digit group, which a plain substring pattern can't
    //    express: a code like "_A_23_202425" (spanning Term 2 and Term 3)
    //    doesn't contain "_A_2_202425" or "_A_3_202425" as a substring at
    //    all. A pattern of "_A_*2*_202425" matches it (and still matches a
    //    plain single-term code like "_A_2_202425" too).
    //
    // 2. Full regex: a pattern wrapped in slashes, e.g. "/pattern/" or with
    //    trailing flags "/pattern/i", is compiled as a regular expression
    //    as-is, for anything the digit wildcard can't express.
    var compilePattern = function (pattern) {
        var regexLiteral = /^\/(.*)\/([a-z]*)$/.exec(pattern);
        if (regexLiteral) {
            try {
                return new RegExp(regexLiteral[1], regexLiteral[2]);
            } catch (e) {
                return null;
            }
        }

        if (pattern.indexOf('*') !== -1) {
            return new RegExp(pattern.split('*').map(escapeRegExp).join('[0-9]*'));
        }

        return null;
    };

    var patternMatches = function (haystack, pattern) {
        if (!patternCache.has(pattern)) {
            patternCache.set(pattern, compilePattern(pattern));
        }
        var regex = patternCache.get(pattern);
        return regex ? regex.test(haystack) : haystack.indexOf(pattern) !== -1;
    };

    var waitForUpdate = function (target, timeout) {
        return new Promise(function (resolve) {
            var settled = false;
            var finish = function () {
                if (settled) {
                    return;
                }
                settled = true;
                observer.disconnect();
                resolve();
            };
            var observer = new MutationObserver(finish);
            observer.observe(target, {childList: true, subtree: true});
            setTimeout(finish, timeout);
        });
    };

    // Waits for an actual [data-region="paged-content-page"] rather than
    // the paging bar: Moodle inserts the paging bar synchronously and
    // immediately clicks page 1 itself, so the bar exists well before any
    // page has actually rendered. Acting on the bar's mere presence races
    // that first fetch - Moodle ignores further clicks while one is already
    // in flight - so we'd wrongly settle for whatever that first fetch
    // alone returned.
    var waitForInitialRender = function (coursesView) {
        return new Promise(function (resolve) {
            var start = Date.now();
            var check = function () {
                if (coursesView.querySelector(SELECTORS.PAGE)) {
                    resolve();
                    return;
                }
                if (Date.now() - start > INITIAL_RENDER_TIMEOUT_MS) {
                    resolve();
                    return;
                }
                setTimeout(check, INITIAL_RENDER_POLL_MS);
            };
            check();
        });
    };

    /**
     * @param {Element} coursesView
     * @param {Element} filterContainer
     * @param {Object} strings
     */
    function CourseFilter(coursesView, filterContainer, strings) {
        this.coursesView = coursesView;
        this.filterContainer = filterContainer;
        this.strings = strings;
        this.allLoaded = false;
        this.loadPromise = null;
        this.filtering = false;
        this.originalActivePage = null;
        this.syncing = false;
        this.courseRolesById = new Map();

        this.countIndicator = document.createElement('div');
        this.countIndicator.className = 'course-count-indicator text-muted small';
        filterContainer.insertAdjacentElement('afterend', this.countIndicator);
    }

    CourseFilter.prototype.saveLayout = function () {
        if (this.filtering) {
            return;
        }
        this.filtering = true;

        var pagingBar = this.coursesView.querySelector(SELECTORS.PAGING_BAR);
        this.originalActivePage = pagingBar ? pagingBar.getAttribute('data-active-page-number') : null;
    };

    CourseFilter.prototype.restoreLayout = function () {
        if (!this.filtering) {
            return;
        }
        this.filtering = false;

        this.coursesView.querySelectorAll(SELECTORS.COURSE_ITEM).forEach(function (card) {
            var column = card.closest(SELECTORS.COLUMN) || card;
            column.style.removeProperty('display');
        });

        if (this.originalActivePage !== null) {
            var originalActivePage = this.originalActivePage;
            this.coursesView.querySelectorAll(SELECTORS.PAGE).forEach(function (page) {
                page.classList.toggle('hidden', page.getAttribute('data-page') !== originalActivePage);
            });
        }

        var pagingControls = this.coursesView.querySelector(SELECTORS.PAGING_CONTROLS);
        if (pagingControls) {
            pagingControls.style.removeProperty('display');
        }
    };

    CourseFilter.prototype.loadAllCourses = function () {
        var self = this;
        if (self.allLoaded) {
            return Promise.resolve();
        }

        if (!self.loadPromise) {
            self.loadPromise = self.loadAllCoursesImpl().finally(function () {
                self.allLoaded = true;
                self.loadPromise = null;
            });
        }

        return self.loadPromise;
    };

    CourseFilter.prototype.loadAllCoursesImpl = function () {
        var self = this;

        return waitForInitialRender(self.coursesView).then(function () {
            var pagingBar = self.coursesView.querySelector(SELECTORS.PAGING_BAR);
            if (!pagingBar) {
                return Promise.resolve();
            }

            var allOption = self.coursesView.querySelector(SELECTORS.LIMIT_ALL_OPTION);
            if (allOption) {
                allOption.click();
                return waitForUpdate(self.coursesView, AJAX_SETTLE_TIMEOUT_MS);
            }

            var clicks = 0;
            var clickNext = function () {
                var next = pagingBar.querySelector(SELECTORS.NEXT_CONTROL);
                if (!next || next.classList.contains('disabled') || clicks >= MAX_NEXT_CLICKS) {
                    return Promise.resolve();
                }
                var link = next.querySelector(SELECTORS.PAGE_LINK) || next;
                link.click();
                clicks++;
                return waitForUpdate(self.coursesView, AJAX_SETTLE_TIMEOUT_MS).then(clickNext);
            };

            return clickNext();
        });
    };

    CourseFilter.prototype.getViewParams = function () {
        return {
            classification: this.coursesView.getAttribute('data-grouping') || 'all',
            sort: this.coursesView.getAttribute('data-sort') || null,
            customfieldname: this.coursesView.getAttribute('data-customfieldname') || null,
            customfieldvalue: this.coursesView.getAttribute('data-customfieldvalue') || null
        };
    };

    CourseFilter.prototype.fetchCourseData = function () {
        var params = this.getViewParams();
        // Wrapped in Promise.resolve() because core/ajax's returned promise
        // doesn't implement .finally() (callers further up the chain, e.g.
        // handleViewChanged(), rely on it) - normalizing here to a native
        // Promise as soon as possible keeps every .then()/.catch()/.finally()
        // downstream of this call native too.
        return Promise.resolve(Ajax.call([{
            methodname: 'block_enhancedcourseoverview_get_courses_with_roles',
            args: {
                classification: params.classification,
                sort: params.sort,
                customfieldname: params.customfieldname,
                customfieldvalue: params.customfieldvalue
            }
        }])[0]).then(function (response) {
            return response.courses || [];
        }).catch(function (e) {
            // eslint-disable-next-line no-console
            console.error('block_enhancedcourseoverview: failed to fetch course/role data', e);
            return null;
        });
    };

    CourseFilter.prototype.getGroupCategory = function (group) {
        return group.dataset.category || DEFAULT_CATEGORY;
    };

    CourseFilter.prototype.rebuildRolesGroup = function (courseData) {
        var self = this;
        var existing = self.filterContainer.querySelector(SELECTORS.GROUP + '[data-category="' + ROLE_CATEGORY + '"]');
        var previouslyActive = new Set();
        if (existing) {
            existing.querySelectorAll(SELECTORS.FILTER_BUTTON + '.active').forEach(function (button) {
                previouslyActive.add(button.getAttribute('data-pattern'));
            });
            existing.remove();
        }

        var roleNamesByShortname = new Map();
        courseData.forEach(function (course) {
            (course.roles || []).forEach(function (role) {
                if (!roleNamesByShortname.has(role.shortname)) {
                    roleNamesByShortname.set(role.shortname, role.name);
                }
            });
        });

        if (roleNamesByShortname.size <= 1) {
            return;
        }

        var group = document.createElement('div');
        group.className = 'btn-group btn-group-sm mb-1';
        group.dataset.category = ROLE_CATEGORY;

        var header = document.createElement('button');
        header.type = 'button';
        header.className = 'btn btn-outline-secondary filter-group-toggle';
        header.setAttribute('aria-pressed', 'false');
        header.textContent = self.strings.rolesgroup;
        group.appendChild(header);

        roleNamesByShortname.forEach(function (name, shortname) {
            var isactive = previouslyActive.has(shortname);
            var button = document.createElement('button');
            button.type = 'button';
            button.className = 'btn btn-outline-primary filter-term-btn' + (isactive ? ' active' : '');
            button.setAttribute('data-pattern', shortname);
            button.setAttribute('aria-pressed', isactive ? 'true' : 'false');
            button.textContent = name;
            group.appendChild(button);
        });

        self.filterContainer.appendChild(group);
        self.wireGroup(group);
    };

    CourseFilter.prototype.updateGroupVisibility = function () {
        var self = this;
        return self.fetchCourseData().then(function (courseData) {
            if (courseData === null) {
                return;
            }

            self.courseRolesById = new Map(courseData.map(function (course) {
                return [String(course.id), new Set((course.roles || []).map(function (role) {
                    return role.shortname;
                }))];
            }));

            self.rebuildRolesGroup(courseData);

            self.filterContainer.querySelectorAll(SELECTORS.GROUP).forEach(function (group) {
                var category = self.getGroupCategory(group);
                var patterns = Array.prototype.map.call(
                    group.querySelectorAll(SELECTORS.FILTER_BUTTON),
                    function (button) {
                        return button.getAttribute('data-pattern');
                    }
                );
                var hasMatch = patterns.some(function (pattern) {
                    return courseData.some(function (course) {
                        if (category === ROLE_CATEGORY) {
                            return (course.roles || []).some(function (role) {
                                return role.shortname === pattern;
                            });
                        }
                        return patternMatches(course.fullname || '', pattern);
                    });
                });
                group.classList.toggle('enhancedcourseoverview-group-hidden', !hasMatch);
            });
        });
    };

    CourseFilter.prototype.applyFilters = function (activeByCategory) {
        var self = this;

        self.coursesView.querySelectorAll(SELECTORS.PAGE).forEach(function (page) {
            page.classList.remove('hidden');
        });
        var pagingControls = self.coursesView.querySelector(SELECTORS.PAGING_CONTROLS);
        if (pagingControls) {
            pagingControls.style.setProperty('display', 'none');
        }

        var categories = Object.keys(activeByCategory).filter(function (category) {
            return activeByCategory[category].length > 0;
        });
        var cards = self.coursesView.querySelectorAll(SELECTORS.COURSE_ITEM);
        var visible = 0;

        cards.forEach(function (card) {
            var column = card.closest(SELECTORS.COLUMN) || card;
            var nameEl = card.querySelector(SELECTORS.COURSE_NAME);
            var haystack = (nameEl ? nameEl.textContent : card.textContent) || '';
            var courseRoles = self.courseRolesById.get(card.getAttribute('data-course-id')) || new Set();

            var matches = categories.every(function (category) {
                var patterns = activeByCategory[category];
                if (category === ROLE_CATEGORY) {
                    return patterns.some(function (pattern) {
                        return courseRoles.has(pattern);
                    });
                }
                return patterns.some(function (pattern) {
                    return patternMatches(haystack, pattern);
                });
            });

            if (matches) {
                column.style.removeProperty('display');
                visible++;
            } else {
                column.style.setProperty('display', 'none', 'important');
            }
        });

        self.toggleEmptyMessage(visible === 0);
        self.countIndicator.textContent = self.strings.showing.replace('{visible}', visible).replace('{total}', cards.length);
    };

    CourseFilter.prototype.toggleEmptyMessage = function (show) {
        var message = this.coursesView.querySelector('.enhancedcourseoverview-empty');

        if (!show) {
            if (message) {
                message.remove();
            }
            return;
        }

        if (!message) {
            message = document.createElement('div');
            message.className = 'alert alert-info enhancedcourseoverview-empty';
            message.textContent = this.strings.nomatches;
            this.coursesView.appendChild(message);
        }
    };

    CourseFilter.prototype.syncButtonStates = function () {
        this.filterContainer.querySelectorAll(SELECTORS.FILTER_BUTTON).forEach(function (button) {
            button.setAttribute('aria-pressed', button.classList.contains('active') ? 'true' : 'false');
        });

        this.filterContainer.querySelectorAll(SELECTORS.GROUP).forEach(function (group) {
            var buttons = group.querySelectorAll(SELECTORS.FILTER_BUTTON);
            var toggle = group.querySelector(SELECTORS.GROUP_TOGGLE);
            if (!toggle || buttons.length === 0) {
                return;
            }
            var activeCount = group.querySelectorAll(SELECTORS.FILTER_BUTTON + '.active').length;
            toggle.classList.toggle('active', activeCount === buttons.length);
            toggle.setAttribute('aria-pressed', activeCount === buttons.length ? 'true' : 'false');
        });
    };

    CourseFilter.prototype.hasActiveFilters = function () {
        return this.filterContainer.querySelector(SELECTORS.FILTER_BUTTON + '.active') !== null;
    };

    CourseFilter.prototype.refresh = function () {
        var self = this;
        self.syncButtonStates();

        var activeByCategory = {};
        self.filterContainer.querySelectorAll(SELECTORS.FILTER_BUTTON + '.active').forEach(function (button) {
            var group = button.closest(SELECTORS.GROUP);
            var category = group ? self.getGroupCategory(group) : DEFAULT_CATEGORY;
            if (!activeByCategory[category]) {
                activeByCategory[category] = [];
            }
            activeByCategory[category].push(button.getAttribute('data-pattern'));
        });

        if (Object.keys(activeByCategory).length === 0) {
            self.restoreLayout();
            self.countIndicator.textContent = '';
            self.toggleEmptyMessage(false);
            return Promise.resolve();
        }

        self.saveLayout();

        var loadPromise = Promise.resolve();
        if (!self.allLoaded) {
            self.countIndicator.textContent = self.strings.loading;
            loadPromise = self.loadAllCourses();
        }

        return loadPromise.then(function () {
            self.applyFilters(activeByCategory);
        });
    };

    CourseFilter.prototype.wireGroup = function (group) {
        var self = this;

        group.querySelectorAll(SELECTORS.FILTER_BUTTON).forEach(function (button) {
            button.addEventListener('click', function (event) {
                event.preventDefault();
                button.classList.toggle('active');
                self.refresh();
            });
        });

        group.querySelectorAll(SELECTORS.GROUP_TOGGLE).forEach(function (toggle) {
            toggle.addEventListener('click', function (event) {
                event.preventDefault();
                var buttons = group.querySelectorAll(SELECTORS.FILTER_BUTTON);
                var allActive = Array.prototype.every.call(buttons, function (button) {
                    return button.classList.contains('active');
                });
                buttons.forEach(function (button) {
                    button.classList.toggle('active', !allActive);
                });
                self.refresh();
            });
        });
    };

    CourseFilter.prototype.handleViewChanged = function () {
        var self = this;
        if (self.syncing) {
            return Promise.resolve();
        }
        self.syncing = true;

        self.allLoaded = false;
        self.filtering = false;

        return self.updateGroupVisibility().then(function () {
            if (self.hasActiveFilters()) {
                return self.refresh();
            }
            return Promise.resolve();
        }).finally(function () {
            self.syncing = false;
        });
    };

    CourseFilter.prototype.watchForViewChanges = function () {
        var self = this;
        var debounceTimer = null;
        var observer = new MutationObserver(function () {
            if (debounceTimer) {
                clearTimeout(debounceTimer);
            }
            debounceTimer = setTimeout(function () {
                self.handleViewChanged();
            }, VIEW_CHANGE_DEBOUNCE_MS);
        });
        observer.observe(self.coursesView, {childList: true, subtree: true});
    };

    /**
     * @param {String} uniqid
     * @return {Promise}
     */
    var init = function (uniqid) {
        var filterContainer = document.getElementById(uniqid);
        if (!filterContainer) {
            return Promise.resolve();
        }

        // Guard against being initialised twice on the same DOM, e.g. if
        // Moodle re-renders this block via AJAX without a full page reload.
        // Without this, every click listener below would get attached a
        // second time, and a single click would fire both, e.g. toggling a
        // button's own "active" class on then back off within the same tap.
        if (filterContainer.dataset.enhancedcourseoverviewInit) {
            return Promise.resolve();
        }
        filterContainer.dataset.enhancedcourseoverviewInit = 'true';

        var block = filterContainer.closest('.block') || document.body;
        var coursesView = block.querySelector(SELECTORS.COURSES_VIEW);
        if (!coursesView) {
            return Promise.resolve();
        }

        return Str.get_strings([
            {key: 'filter:loading', component: 'block_enhancedcourseoverview'},
            {key: 'filter:nomatches', component: 'block_enhancedcourseoverview'},
            {key: 'filter:showing', component: 'block_enhancedcourseoverview'},
            {key: 'filter:rolesgroup', component: 'block_enhancedcourseoverview'}
        ]).then(function (strings) {
            var filter = new CourseFilter(coursesView, filterContainer, {
                loading: strings[0],
                nomatches: strings[1],
                showing: strings[2],
                rolesgroup: strings[3]
            });

            filterContainer.querySelectorAll(SELECTORS.GROUP).forEach(function (group) {
                filter.wireGroup(group);
            });

            filter.watchForViewChanges();

            return filter.updateGroupVisibility().then(function () {
                return filter.refresh();
            });
        });
    };

    return {
        init: init
    };
});
